\encoding UTF8
\copy (SELECT json_build_object('id', q.id, 'subject', q.subject_area, 'q', q.question_text, 'a', q.option_a, 'b', q.option_b, 'c', q.option_c, 'd', q.option_d, 'e', q.option_e, 'key', q.correct_answer, 'status', q.quality_review_status) FROM question_bank q WHERE q.id IN (SELECT id FROM v_safe_for_beta) AND NOT (q.pipeline_metadata::jsonb ? 'consensus_2signal_run') AND NOT (q.pipeline_metadata::jsonb ? 'math_promote_run') AND NOT (q.pipeline_metadata::jsonb ? 'verbal_promote_run') AND q.correct_answer IN ('A','B','C','D','E') AND q.option_a IS NOT NULL AND q.option_b IS NOT NULL AND q.option_c IS NOT NULL AND q.option_d IS NOT NULL AND q.option_e IS NOT NULL AND q.word_count >= 5 AND (length(q.question_text)-length(replace(q.question_text,'$','')))%2 = 0 ORDER BY md5(q.id) LIMIT 50) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_served_audit/master.csv' CSV
